// Normalise the photo field from both branches into a single 'processedImage' key.
// TRUE branch: imageBase64 stays untouched.
// FALSE branch: Privacy Blur API returns { processed_image }.
const item = $input.first().json;

const processedImage =
  item.processed_image   // came from blur endpoint
  ?? item.imageBase64    // came from consent-OK branch
  ?? null;

return [{
  json: {
    ...item,
    processedImage,
    processed_image: undefined   // clean up
  }
}];

