parameters.jsCode:
// After QR Engine responds, merge its output with the upstream review data.
// The QR node only emits { image, brand_color, preview_mode } — we need
// all the review fields too (cafeId, reservationId, reviewText, etc.).
// Use $('Code — Normalise Photo Field').first().json to get the full context.
const review = $('Code — Normalise Photo Field').first().json;
const qr     = $input.first().json;

return [{
  json: {
    ...review,
    qrImageBase64 : qr.image,
    brandColor    : qr.brand_color,
    qrPreviewMode : qr.preview_mode
  }
}];

// Assemble the final payload to POST to our Express API.
// Pull QR URL from the Cloudinary QR upload node.
// Pull review photo URL from the photo upload (or empty string).
const review   = $('Code — Merge QR + Review Data').first().json;
const qrUpload = $('HTTP — Cloudinary Upload QR').first().json;
const photoUrl = $input.first().json.secure_url ?? '';

return [{
  json: {
    cafeId              : review.cafeId,
    reservationId       : review.reservationId,
    imageUrl            : photoUrl,
    qrCodeUrl           : qrUpload.secure_url,
    reviewText          : review.reviewText,
    rating              : review.rating,
    userConsentGranted  : review.userConsentGranted,
    brandColor          : review.brandColor,
    moderationStatus    : 'pending'
  }
}];

